                                         Color.Red, 0, ButtonBorderStyle.Solid,
                                         Color.FromArgb(87, 155, 177), 1, ButtonBorderStyle.Solid,
                                         Color.FromArgb(87, 155, 177), 1, ButtonBorderStyle.Solid);
